"""Real process crashes during setup must not invent a restored transaction.

Breaks caught: missing pre-dispatch WAL, treating missing evidence as no effect,
overwriting partial setup/external files, ignoring a live operation lock, or
mistaking an initialized transaction for an abortable setup. No device access.
"""
import fcntl
import json
import os
from pathlib import Path
import subprocess
import tempfile
import unittest


REPO = Path(__file__).resolve().parents[1]


def setup_header():
    # Independent OS observations, not bytes generated by the production code.
    if Path("/proc/sys/kernel/random/boot_id").exists():
        boot = Path("/proc/sys/kernel/random/boot_id").read_text().strip()
        return f"setup\nprobe_v1\n{boot}\n{os.readlink('/proc/self/ns/mnt')}\n".encode()
    return b"setup\nprobe_v1\nhost_fixture_only\n"


class SetupRecoveryTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.build = tempfile.TemporaryDirectory(prefix="mt6639-setup-build-")
        cls.binary = Path(cls.build.name) / "probe"
        cls.fault = Path(cls.build.name) / "probe-fault"
        common = ["cc", "-std=c11", "-D_POSIX_C_SOURCE=200809L", "-Wall",
                  "-Wextra", "-Werror", "-O2"]
        source = str(REPO / "native/recovery/probe.c")
        for output, extra in ((cls.binary, []), (cls.fault, [
                "-Dfsync=mt_test_setup_fsync", str(REPO / "tests/native_setup_fault.c")])):
            run = subprocess.run(common + [source] + extra + ["-o", str(output)],
                                 capture_output=True, text=True, timeout=30)
            if run.returncode:
                raise AssertionError(run.stderr)

    @classmethod
    def tearDownClass(cls):
        cls.build.cleanup()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix="mt6639-setup-test-")
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)

    def call(self, command="probe-recover", fault_at=None, action="kill", root=None):
        root = root or self.root
        argv = [str(self.fault if fault_at else self.binary), command, str(root)]
        if command == "probe-run":
            argv += ["0", "1000"]
        env = dict(os.environ, MT_TEST_FSYNC_AT=str(fault_at or 0),
                   MT_TEST_FSYNC_ACTION=action)
        return subprocess.run(argv, env=env, capture_output=True, text=True, timeout=3)

    def crash_setup(self, boundary, root=None):
        run = self.call("probe-run", fault_at=boundary, root=root)
        self.assertEqual(run.returncode, -9, (run.stdout, run.stderr))
        self.assertFalse(((root or self.root) / "process").exists())
        if boundary >= 2:
            self.assertTrue(((root or self.root) / "journal").exists(),
                            "setup artifacts were created before any setup WAL")

    def assert_aborted(self, root=None):
        root = root or self.root
        run = self.call(root=root)
        self.assertEqual(run.returncode, 0, (run.stdout, run.stderr))
        self.assertEqual(json.loads(run.stdout), {
            "event": "result", "operation": "recovered",
            "recovery": "not_applied", "code": 0})
        self.assertEqual((root / "journal").read_bytes(), setup_header() + b"abort_intent\naborted\n")
        return run

    def test_killed_at_each_complete_setup_boundary_can_abort_without_rewriting(self):
        # journal file/dir, environment file/dir, lock file/dir, fixture
        # file/dir, identity file/dir, stage file/dir. No worker is authorized.
        for boundary in range(2, 14):
            with self.subTest(boundary=boundary):
                root = self.root / str(boundary)
                root.mkdir(mode=0o700)
                self.crash_setup(boundary, root)
                before = {p.name: (p.stat().st_ino, p.read_bytes())
                          for p in root.iterdir() if p.name != "journal"}
                self.assert_aborted(root)
                after = {p.name: (p.stat().st_ino, p.read_bytes())
                         for p in root.iterdir() if p.name != "journal"}
                self.assertEqual(after, before, "abort changed setup artifacts")
                self.assert_aborted(root)  # Durable/idempotent, not a re-apply.
                rerun = self.call("probe-run", root=root)
                self.assertEqual(rerun.returncode, 3, rerun.stdout)

    def test_fsync_failure_leaves_a_recoverable_explicit_setup(self):
        run = self.call("probe-run", fault_at=4, action="fail")
        self.assertNotEqual(run.returncode, 0)
        self.assert_aborted()

    def test_before_record_forbids_using_setup_abort_path(self):
        self.crash_setup(14)
        run = self.call()
        self.assertEqual(run.returncode, 0, (run.stdout, run.stderr))
        self.assertEqual(json.loads(run.stdout)["recovery"], "restored")
        self.assertEqual((self.root / "fixture").read_bytes(), b"baseline\n")
        self.assertNotIn(b"aborted", (self.root / "journal").read_bytes())

    def test_missing_journal_is_not_evidence_of_no_effect(self):
        self.crash_setup(1)
        run = self.call()
        self.assertEqual(run.returncode, 3, run.stdout)
        self.assertFalse((self.root / "journal").exists())

    def test_torn_setup_wal_is_preserved_and_blocked(self):
        self.crash_setup(2)
        (self.root / "journal").write_bytes(b"setu")
        run = self.call()
        self.assertEqual(run.returncode, 3, run.stdout)
        self.assertEqual((self.root / "journal").read_bytes(), b"setu")

    def test_external_fixture_content_blocks_abort_without_overwrite(self):
        self.crash_setup(8)
        (self.root / "fixture").write_bytes(b"external\n")
        run = self.call()
        self.assertEqual(run.returncode, 3, run.stdout)
        self.assertEqual((self.root / "fixture").read_bytes(), b"external\n")
        self.assertEqual((self.root / "journal").read_bytes(), setup_header())

    def test_same_bytes_different_recorded_inode_blocks_abort(self):
        self.crash_setup(10)
        other = self.root / "other"
        other.write_bytes(b"baseline\n")
        other.chmod(0o600)
        other.replace(self.root / "fixture")
        run = self.call()
        self.assertEqual(run.returncode, 3, run.stdout)
        self.assertEqual((self.root / "journal").read_bytes(), setup_header())

    def test_symlink_in_optional_setup_object_blocks_without_following(self):
        self.crash_setup(2)
        outside = self.root / "outside"
        outside.write_bytes(b"keep\n")
        (self.root / "op.lock").symlink_to(outside)
        run = self.call()
        self.assertEqual(run.returncode, 3, run.stdout)
        self.assertEqual(outside.read_bytes(), b"keep\n")

    def test_live_operation_lock_blocks_even_unfinished_setup(self):
        self.crash_setup(8)
        with (self.root / "op.lock").open("rb") as stream:
            fcntl.flock(stream, fcntl.LOCK_EX | fcntl.LOCK_NB)
            run = self.call()
            self.assertEqual(run.returncode, 2, run.stdout)
        self.assertEqual((self.root / "journal").read_bytes(), setup_header())
        self.assert_aborted()

    def test_process_record_in_setup_cannot_be_called_not_applied(self):
        self.crash_setup(8)
        path = self.root / "process"
        path.write_bytes(b"untrusted-process\n")
        path.chmod(0o600)
        run = self.call()
        self.assertEqual(run.returncode, 3, run.stdout)
        self.assertEqual(path.read_bytes(), b"untrusted-process\n")

    def test_cooperative_cancel_before_release_is_not_applied(self):
        run = self.call("probe-run", fault_at=13, action="term")
        self.assertEqual(run.returncode, 0, (run.stdout, run.stderr))
        self.assertEqual(json.loads(run.stdout), {
            "event": "result", "operation": "cancelled",
            "recovery": "not_applied", "code": 0})
        self.assertFalse((self.root / "process").exists())
        self.assertTrue((self.root / "journal").read_bytes().endswith(b"abort_intent\naborted\n"))

    def test_prepared_object_drift_is_rejected_before_worker_release(self):
        run = self.call("probe-run", fault_at=13, action="drift")
        self.assertEqual(run.returncode, 3, (run.stdout, run.stderr))
        self.assertFalse((self.root / "process").exists(), "drifted preparation launched a worker")
        self.assertEqual((self.root / "journal").read_bytes(), setup_header())
        self.assertEqual((self.root / "fixture").read_bytes(), b"external\n")

    def test_missing_prepared_stage_is_rejected_before_worker_release(self):
        run = self.call("probe-run", fault_at=13, action="remove-stage")
        self.assertEqual(run.returncode, 3, (run.stdout, run.stderr))
        self.assertFalse((self.root / "process").exists(), "incomplete preparation launched a worker")
        self.assertEqual((self.root / "journal").read_bytes(), setup_header())
        self.assertFalse((self.root / "stage").exists())

    def test_changed_environment_blocks_setup_abort(self):
        self.crash_setup(4)
        (self.root / "environment").write_bytes(b"probe_v1\ndifferent_boot\n")
        run = self.call()
        self.assertEqual(run.returncode, 3, run.stdout)

    def test_unsafe_fixture_mode_blocks_setup_abort(self):
        self.crash_setup(8)
        (self.root / "fixture").chmod(0o644)
        run = self.call()
        self.assertEqual(run.returncode, 3, run.stdout)

    def test_crash_after_abort_intent_can_resume_without_touching_fixture(self):
        self.crash_setup(8)
        inode = (self.root / "fixture").stat().st_ino
        run = self.call(fault_at=2)
        self.assertEqual(run.returncode, -9, run.stdout)
        self.assertEqual((self.root / "journal").read_bytes(), setup_header() + b"abort_intent\n")
        self.assert_aborted()
        self.assertEqual((self.root / "fixture").stat().st_ino, inode)

    def test_aborted_setup_rechecks_external_drift(self):
        self.crash_setup(8)
        self.assert_aborted()
        (self.root / "fixture").write_bytes(b"external\n")
        run = self.call()
        self.assertEqual(run.returncode, 3, run.stdout)
        self.assertEqual((self.root / "fixture").read_bytes(), b"external\n")

    def test_identity_without_fixture_is_not_a_valid_setup(self):
        self.crash_setup(10)
        (self.root / "fixture").unlink()  # Deliberate fixture-only conflict.
        run = self.call()
        self.assertEqual(run.returncode, 3, run.stdout)

    def test_setup_header_without_boot_namespace_never_implies_not_applied(self):
        self.crash_setup(2)
        (self.root / "journal").write_bytes(b"setup\n")
        run = self.call()
        self.assertEqual(run.returncode, 3, run.stdout)
        self.assertEqual((self.root / "journal").read_bytes(), b"setup\n")

    def test_illegal_setup_transitions_are_not_closed(self):
        self.crash_setup(8)
        for suffix in (b"intent\n", b"aborted\n", b"restore_intent\n", b"before\nabort_intent\n",
                       b"abort_intent\naborted\nbefore\n"):
            with self.subTest(suffix=suffix):
                journal = setup_header() + suffix
                (self.root / "journal").write_bytes(journal)
                run = self.call()
                self.assertEqual(run.returncode, 3, run.stdout)
                self.assertEqual((self.root / "journal").read_bytes(), journal)

    def test_legacy_before_first_closed_journal_is_still_readable(self):
        run = self.call("probe-run")
        self.assertEqual(run.returncode, 0, run.stdout)
        current = (self.root / "journal").read_bytes()
        self.assertTrue(current.startswith(setup_header()))
        legacy = current[len(setup_header()):]
        self.assertEqual(legacy, b"before\nintent\napplied\nrestore_intent\nrestored\nclosed\n")
        (self.root / "journal").write_bytes(legacy)
        run = self.call()
        self.assertEqual(run.returncode, 0, run.stdout)
        self.assertEqual(json.loads(run.stdout)["recovery"], "restored")
        self.assertEqual((self.root / "journal").read_bytes(), legacy)


if __name__ == "__main__":
    unittest.main()
